$("mpGenerate").addEventListener("click",async()=>{const b=$("mpGenerate");b.disabled=true;$("mpResearchStatus").textContent="Gathering data and preparing daily research…";try{if(!lastAssets.length)lastAssets=await fetchAssets();renderAssets(lastAssets);const macro=await getMacro();const marketGroups=await getAllCrossAssetData();const report=await callBackend("/api/daily-brief",{assets:lastAssets,macro,marketGroups,asOf:new Date().toISOString()});const host=$("mpBrief");host.replaceChildren();const sections=Array.isArray(report.sections)?report.sections:[{title:"AI Research Report",content:report.answer||report.report||JSON.stringify(report,null,2)}];sections.forEach((s,i)=>{const box=document.createElement("section");const h=document.createElement("h3");h.textContent=String(i+1).padStart(2,"0")+" / "+(s.title||"Research");const p=document.createElement("p");renderAnswer(p,s.content||"No findings returned.");box.append(h,p);host.append(box);});$("mpResearchStatus").textContent="Brief generated "+new Date(report.generatedAt||Date.now()).toLocaleString()+".";}catch(err){$("mpResearchStatus").textContent=err.message;}finally{b.disabled=false;}});
async function checkAIService(){try{const response=await fetch(ANALYST_API_BASE+"/health",{cache:"no-store"});const data=await response.json();if(!response.ok||!data.ok)throw new Error("Service health check failed");$("mpChatState").textContent="Online · "+(data.provider||"AI service");$("mpChatStatus").textContent="Provider: "+data.provider+" · model: "+data.model+" · market quote freshness varies by provider.";if($("mpBackend"))$("mpBackend").textContent=(data.provider||"AI service")+" · "+(data.model||"connected");}catch(error){$("mpChatState").textContent="Connection issue";$("mpChatStatus").textContent="Could not reach MarketPilot AI service: "+error.message;}}checkAIService();refreshAssets();showMarketGroup("crypto");setView("markets");
